import React, { useState } from 'react';
import { Link, useNavigate } from "react-router-dom";
import './loginPage.css';

const LoginPage = () => {
  const [step, setStep] = useState(1);
  const [role, setRole] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [errors, setErrors] = useState({});
  const navigate = useNavigate();

  const handleRoleSelect = (role) => {
    setRole(role);
    setStep(2);
  };

  const validateEmail = (email) => {
    const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailPattern.test(email);
  };

  const validatePassword = (password) => {
    const passwordPattern = /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,}$/;
    return passwordPattern.test(password);
  };

  const handleLoginSubmit = (e) => {
    e.preventDefault();
    const newErrors = {};

    // Validate Empty Fields
    if (!email.trim()) {
      newErrors.email = "Email is required.";
    } else if (!validateEmail(email)) {
      newErrors.email = "Please enter a valid email address.";
    }

    if (!password.trim()) {
      newErrors.password = "Password is required.";
    } else if (!validatePassword(password)) {
      newErrors.password = "Password must be at least 8 characters, with 1 uppercase, 1 lowercase, 1 number, and 1 special character.";
    }

    // Set errors if any exist
    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }

    // Proceed with login
    if (role === "Student") {
      navigate("/dashboard/student");
    } else if (role === "Supervisor") {
      navigate("/dashboard/supervisor");
    } else if (role === "Admin") {
      navigate("/dashboard/admin");
    }
  };

  return (
    <div className="login-container">
      {step === 2 && (
        <button className="back-button" onClick={() => setStep(1)}>
          <i className="fas fa-arrow-left"></i>
        </button>
      )}

      {step === 1 && (
        <div className="role-selection">
          <h2>Select Your Role</h2>
          <div className="role-buttons">
            <button onClick={() => handleRoleSelect('Admin')}>Admin</button>
            <button onClick={() => handleRoleSelect('Supervisor')}>Supervisor</button>
            <button onClick={() => handleRoleSelect('Student')}>Student</button>
          </div>
        </div>
      )}

      {step === 2 && role && (
        <div className="login-form">
          <h2>Login as {role}</h2>
          <form onSubmit={handleLoginSubmit}>
            <div className="input-container">
              <i className="fas fa-envelope"></i>
              <input
                type="email"
                placeholder="Enter your email"
                value={email}
                onChange={(e) => {
                  setEmail(e.target.value);
                  setErrors((prev) => ({ ...prev, email: "" }));
                }}
              />
              {errors.email && <p className="error-message">{errors.email}</p>}
            </div>

            <div className="input-container">
              <i className="fas fa-lock"></i>
              <input
                type="password"
                placeholder="Enter your password"
                value={password}
                onChange={(e) => {
                  setPassword(e.target.value);
                  setErrors((prev) => ({ ...prev, password: "" }));
                }}
              />
              {errors.password && <p className="error-message">{errors.password}</p>}
            </div>
            
            <button type="submit" className="login-button">Login</button>
          </form>

          {role === "Student" && (
            <div className="sign-up-option">
              <p>Don't have an account? <Link to="/signup">Sign up here</Link></p>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default LoginPage;
